// File-arrival trigger: run when new files land
{
  "name": "ingest_on_arrival",
  "trigger": {
    "pause_status": "UNPAUSED",
    "file_arrival": {
      "url": "s3://landing/orders/",
      "min_time_between_triggers_seconds": 60,
      "wait_after_last_change_seconds": 30
    }
  },
  "tasks": [ { "task_key": "autoloader_ingest",
               "notebook_task": { "notebook_path": "/Repos/prod/ingest/autoloader" } } ]
}

// Continuous trigger: keep exactly one run always active
{
  "name": "streaming_ingest",
  "continuous": { "pause_status": "UNPAUSED" },
  "tasks": [ { "task_key": "stream",
               "notebook_task": { "notebook_path": "/Repos/prod/ingest/stream" } } ]
}
